const crypto = require('crypto');
const headers = Object.fromEntries(Object.entries($json.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value]));
const actual = Buffer.from(String(headers.authorization ?? ''), 'utf8');
const expectedSecret = String($env.ALERTMANAGER_WEBHOOK_TOKEN ?? '');
if (expectedSecret.length === 0) throw new Error('ALERTMANAGER_WEBHOOK_TOKEN is not configured; refusing delivery');
const expected = Buffer.from('Bearer ' + expectedSecret, 'utf8');
const authenticated = actual.length === expected.length && crypto.timingSafeEqual(actual, expected);
return { json: { ...$json, AUTHENTICATED: authenticated } };

const payload = $json.body ?? {};
const status = payload.status === 'resolved' ? 'resolved' : 'firing';
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
const room = String($env.ALERTMANAGER_MATRIX_ROOM_ID ?? '').trim() || '!GfJXfhwgQXrmCRRjlf:beaco.works';
const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const labelKeys = ['alertname', 'severity', 'namespace', 'node', 'pod'];
const annotationKeys = ['summary', 'description'];
const render = (alert) => {
  const labels = labelKeys
    .map((key) => [key, alert.labels?.[key]])
    .filter(([, value]) => typeof value === 'string' && value.trim() !== '');
  const notes = annotationKeys
    .map((key) => alert.annotations?.[key])
    .filter((value) => typeof value === 'string' && value.trim() !== '');
  return { head: alert.labels?.alertname ?? 'alert', meta: labels.map(([key, value]) => `${key}=${value}`), notes };
};
const rows = alerts.slice(0, 20).map(render);
const emoji = status === 'resolved' ? '✅' : '🔥';
const htmlRows = rows.map((row) => {
  const meta = row.meta.length ? ` <i>(${row.meta.map(escapeHtml).join(', ')})</i>` : '';
  const notes = row.notes.length ? ` — ${row.notes.map(escapeHtml).join(' | ')}` : '';
  return `<li><b>${escapeHtml(row.head)}</b>${meta}${notes}</li>`;
}).join('');
const suffix = alerts.length > rows.length ? ` <i>(…and ${alerts.length - rows.length} more)</i>` : '';
const messageHtml = `<b>${emoji} Alertmanager ${status}</b>${suffix}<ul>${htmlRows}</ul>`;
const messageText = rows.length
  ? rows.map((row) => `- ${row.head}${row.meta.length ? ` (${row.meta.join(', ')})` : ''}${row.notes.length ? ` — ${row.notes.join(' | ')}` : ''}`).join('\n')
  : `- (no alert details)`;
return { json: { ROOM: room, STATUS: status, ALERT_COUNT: alerts.length, MESSAGE_HTML: messageHtml, MESSAGE_TEXT: messageText } };
